"""Historical 2025 test windows, generated by the actual C++ DPI reference."""
from pathlib import Path
import ctypes,json,math,subprocess,hashlib
import numpy as np
import pandas as pd
R=Path(__file__).resolve().parents[1];B=R/'hardware/tb/build/historical';B.mkdir(parents=True,exist_ok=True)
subprocess.run(['g++','-std=c++17','-shared','-fPIC','-O2',str(R/'hardware/tb/dpi/ols_dpi.cpp'),'-o',str(B/'reference.so')],check=True)
lib=ctypes.CDLL(str(B/'reference.so'));I=ctypes.c_int;L=ctypes.c_longlong;P=ctypes.c_void_p
lib.ols_ref_create.argtypes=[I,I,I];lib.ols_ref_create.restype=P
lib.ols_ref_push.argtypes=[P,I,ctypes.POINTER(I),ctypes.POINTER(L),ctypes.POINTER(L)];lib.ols_ref_push.restype=I
lib.ols_ref_destroy.argtypes=[P]
if lib.ols_ref_selftest()!=1:raise RuntimeError('C++ self-test failed')
m=json.loads((R/'software/models_cpp/model.json').read_text());coeff=[int(math.copysign(math.floor(abs(m[k])*scale+.5),m[k])) for k,scale in [('a',16384),('b',16384),('c',256)]]
d=pd.read_csv(R/'data/processed/temperature.csv',index_col=0,parse_dates=True).iloc[:,0].asfreq('h').loc['2024-12-31 00:00':'2025-12-31 20:00']
if d.isna().any() or len(d)!=8781:raise ValueError('Historical stream must be complete and contiguous')
raw=np.copysign(np.floor(abs(d.to_numpy())*256+.5),d.to_numpy()).astype(int);handle=lib.ols_ref_create(*coeff)
if not handle:raise RuntimeError('Reference creation failed')
path=B/'temperature_2025.txt';eligible=0
with path.open('w') as f:
 f.write(' '.join(map(str,coeff))+'\n')
 for t in raw:
  prediction=I();s=L();scaled=L();valid=lib.ols_ref_push(handle,int(t),ctypes.byref(prediction),ctypes.byref(s),ctypes.byref(scaled))
  if valid<0:raise RuntimeError('Reference rejected sample')
  f.write(f'{t} {valid} {prediction.value}\n');eligible+=valid
lib.ols_ref_destroy(handle)
manifest={'input_start':str(d.index[0]),'input_end':str(d.index[-1]),'accepted_inputs':len(d),'forecasts':eligible,'first_forecast_input_time':'2025-01-01 00:00 UTC','last_forecast_target_time':'2025-12-31 23:00 UTC','coefficients':coeff,'vector_sha256':hashlib.sha256(path.read_bytes()).hexdigest()}
(R/'docs/reports/temperature_historical_manifest.json').write_text(json.dumps(manifest,indent=2));print('C++ historical vectors generated:',len(d),'inputs,',eligible,'forecasts')
